<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ClientIdentity\Domain\ValueObject;

use Civi\Lughauth\Features\Access\RelyingParty\Domain\RelyingPartyRef;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class ClientIdentityRelyingPartyVO
{
    public static function empty(): ClientIdentityRelyingPartyVO
    {
        return new ClientIdentityRelyingPartyVO(null);
    }
    public static function from(ClientIdentityRelyingPartyVO|RelyingPartyRef|null $value): ClientIdentityRelyingPartyVO
    {
        return self::fromUnsafe($value);
    }
    public static function tryFrom(mixed $value, ConstraintFailList $list): ?ClientIdentityRelyingPartyVO
    {
        if ($value instanceof ClientIdentityRelyingPartyVO) {
            // If is a ValueObject, its already validated... nothing to append
            return $value;
        } elseif (!$value) {
            return new ClientIdentityRelyingPartyVO($value);
        } elseif (is_a($value, RelyingPartyRef::class)) {
            return new ClientIdentityRelyingPartyVO($value);
        } else {
            $list->add(new ConstraintFail('wrong_type', ['relyingParty'], [$value], ['RelyingPartyRef']));
            return null;
        }
    }
    private static function fromUnsafe(mixed $value): ClientIdentityRelyingPartyVO
    {
        if ($value instanceof ClientIdentityRelyingPartyVO) {
            // If is a ValueObject, its already validated
            return $value;
        } else {
            // If is not a ValueObject, validation is need and exception throw
            $errorsList = new ConstraintFailList();
            $candidate = self::tryFrom($value, $errorsList);
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            \assert($candidate instanceof ClientIdentityRelyingPartyVO);
            return $candidate;
        }
    }
    /**
     * private constructor to avoid build a value without all the rule validations.
     */
    private function __construct(
        private readonly ?RelyingPartyRef $relyingParty
    ) {
    }
    public function value(): ?RelyingPartyRef
    {
        return $this->relyingParty;
    }
    public function equals(?ClientIdentityRelyingPartyVO $other): bool
    {
        return $this->value()?->uid() == $other?->value()?->uid();
    }
}
